#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    string s;
    cin >> s;

    int seen[26] = {0}, total = 0;
    for (char ch : s) {
        if (!seen[ch - 'a']) total++;
        seen[ch - 'a'] = 1;
    }
    int count[26] = {0};
    int distinct = 0, l = 0, best = s.size();
    for (int rr = 0; rr < (int) s.size(); rr++) {
        int c = s[rr] - 'a';
        if (count[c] == 0) distinct++;
        count[c]++;
        while (distinct == total) {
            best = min(best, rr - l + 1);
            int d = s[l] - 'a';
            count[d]--;
            if (count[d] == 0) distinct--;
            l++;
        }
    }
    cout << best << "\n";

    return 0;
}

